    always_comb begin
        fub_axi_awready = 1'b0;
        case (comb_slave_select_aw)
            13'b0000001000000: begin  // Slave 6 (64b)
                fub_axi_awready = monbus_wr_64b_awready;
            end
            13'b0010000000000: begin  // Slave 10 (64b)
                fub_axi_awready = monbus_wr_64b_awready;
            end
            default: begin
                // No slave selected
            end
        endcase
    end

