    always_comb begin
        fub_axi_wready = 1'b0;
        case (w_slave_select)
            13'b0000001000000: begin  // Slave 6 (64b)
                fub_axi_wready = monbus_wr_64b_wready;
            end
            13'b0010000000000: begin  // Slave 10 (64b)
                fub_axi_wready = monbus_wr_64b_wready;
            end
            default: begin
                // No active W transaction
            end
        endcase
    end

    // Write response MUX (B channel - uses b_slave_select FIFO head)
    always_comb begin
        fub_axi_bid = 8'd0;
        fub_axi_bresp = 2'b00;
        fub_axi_bvalid = 1'b0;

        case (b_slave_select)
            13'b0000001000000: begin  // Slave 6 (64b)
                fub_axi_bid = monbus_wr_64b_b.id;
                fub_axi_bresp = monbus_wr_64b_b.resp;
                fub_axi_bvalid = monbus_wr_64b_bvalid;
            end
            13'b0010000000000: begin  // Slave 10 (64b)
                fub_axi_bid = monbus_wr_64b_b.id;
                fub_axi_bresp = monbus_wr_64b_b.resp;
                fub_axi_bvalid = monbus_wr_64b_bvalid;
            end
            default: begin
                // No slave selected - hold defaults
            end
        endcase
    end

